"""Write the measured preparation report and historical-artifact audit."""
from __future__ import annotations

import argparse
import csv
import io
import json
import subprocess
import sys
from collections import Counter
from pathlib import Path

import av
import pandas as pd
import PIL

from code.e0.dataset import atomic_write_json, atomic_write_text, sha256_file, stable_hash
from .build import DEFAULT_OUT, PARTITIONS, read_jsonl


def table(headers, rows):
    return "\n".join(["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |", *["| " + " | ".join(str(v) for v in row) + " |" for row in rows]])


def report(out):
    project = Path(__file__).resolve().parents[2]
    counts = json.loads((out / "counts.json").read_text())
    manifest = json.loads((out / "split_manifest.json").read_text())
    benchmark = json.loads((out / "benchmark_overlap.json").read_text())
    audit = json.loads((out / "timestamp_leakage_audit.json").read_text())
    sample_audit = json.loads((out / "sample_audit.json").read_text())
    issues = json.loads((out / "source_annotation_issues.json").read_text())
    dimensions = counts["dimensions"]
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=["partition", "participant", "task", "kind", "category", "count"])
    writer.writeheader(); writer.writerows(dimensions)
    atomic_write_text(out / "counts.csv", buffer.getvalue())
    def total(partition=None, person=None, task=None, kind="accepted", category=None):
        return sum(x["count"] for x in dimensions if (partition is None or x["partition"] == partition) and (person is None or x["participant"] == person) and (task is None or x["task"] == task) and x["kind"] == kind and (category is None or x["category"] == category))
    paths = [out / "split_manifest.json", out / "counts.json", out / "reason_review.csv", out / "benchmark_overlap.json", out / "timestamp_leakage_audit.json"]
    paths.extend(out / "swift" / f"{p}.jsonl" for p in PARTITIONS)
    files = {}
    for name in ("e0", "e1_online_why", "e1_local_why"):
        for f in sorted((project / "runs" / name).rglob("*")):
            if f.is_file():
                s = f.stat(); files[str(f.relative_to(project))] = {"bytes": s.st_size, "mtime_ns": s.st_mtime_ns}
    baseline = out / "preservation_before.json"
    preserved = None
    git_changes_preserved = None
    if baseline.exists():
        before = json.loads(baseline.read_text())
        preserved = files == before["historical_artifacts"]
        after_status = set(subprocess.check_output(["git", "status", "--porcelain", "--untracked-files=normal"], cwd=project, text=True).splitlines())
        git_changes_preserved = set(before["git_status"].splitlines()).issubset(after_status)
        if not preserved:
            raise ValueError("Historical E0/E1 artifact tree changed during preparation")
    atomic_write_json(out / "preservation_audit.json", {"historical_artifacts_unchanged": preserved, "preexisting_git_status_entries_preserved": git_changes_preserved, "historical_artifact_count": len(files), "tree_hash": stable_hash(files), "method": "all historical artifact paths, byte sizes, and nanosecond modification times compared against the saved before snapshot; immutable benchmark split SHA256 checked separately; preexisting Git status entries retained", "benchmark_reference_hashes": benchmark["reference_hashes"]})
    for filename, digest in benchmark["reference_hashes"].items():
        if sha256_file(Path(filename)) != digest:
            raise ValueError(f"Historical benchmark metadata changed: {filename}")
    hashes = {str(path.relative_to(out)): sha256_file(path) for path in paths}
    atomic_write_json(out / "artifact_hashes.json", hashes)
    code_paths = sorted((project / "code/hdepic_preparation").glob("*.py")) + [project / "scripts" / name for name in ("build_hdepic_supervision.py", "extract_frames.py", "make_swift_sft.py", "prepare_hdepic_sft.sh")]
    atomic_write_json(out / "build_provenance.json", {"python": sys.version, "pandas": pd.__version__, "PyAV": av.__version__, "Pillow": PIL.__version__, "code_sha256": {str(path.relative_to(project)): sha256_file(path) for path in code_paths}, "rerun_command": f"cd {project} && bash scripts/prepare_hdepic_sft.sh", "training_started": False, "model_calls": 0, "status": "pending_human_reason_label_review"})
    lines = ["# HD-EPIC local dataset preparation", "", "**PENDING HUMAN REASON-LABEL REVIEW. Preparation only: no model inference, external inference API, or training was run.**", "", f"The local annotations contain {counts['annotation_actions']:,} action rows in {counts['videos']} videos. Independently probed video duration is {counts['video_hours']:.9f} hours. These are measured source-video hours, not the duration covered by accepted examples.", "", "No training-specific participant-disjoint manifest or the three requested preparation scripts existed in the inspected repository. The E0 development split is a question split across all nine participants and is not a training split. This preparation uses P01–P06 for training, P07 for validation, and P08–P09 for test. Existing E0/E1 helpers for atomic writes, hashes, source fingerprints and endpoint-inclusive uniform source-frame indices were reused. Existing E0/E1 artifacts and user files were left in place.", "", "## Fixed partitions", "", table(["Partition", "Participants", "Videos", "Hours", "Explain", "Track", "Total"], [[p, ", ".join(manifest['partitions'][p]['participants']), manifest['partitions'][p]['video_count'], f"{manifest['partitions'][p]['duration_hours']:.6f}", total(p, task='explain'), total(p, task='track'), counts['partition_records'][p]] for p in PARTITIONS]), "", f"Second stage is {manifest['second_stage_selection']['video_count']} of {manifest['second_stage_selection']['training_video_count']} training-participant videos ({manifest['second_stage_selection']['fraction']:.4%}). Largest-remainder allocation distributes approximately one sixth across all six participants, then a fixed SHA256 ranking selects videos. Seed: 20261002. Every example from these videos is excluded from initial SFT. Extra-SFT and GRPO must both use the exact same second_stage records and scoring sidecar; this preparation does not implement either training method.", "", "All explicit video IDs are frozen in [split_manifest.json](split_manifest.json). Per-participant reservations: " + ", ".join(f"{p}: {n}" for p, n in manifest['second_stage_selection']['allocations'].items()) + ".", "", "## Input and target protocol", "", "Explain queries at the target action's annotated end, matching the E1 endpoint convention. Track queries are sampled at 0, 5, 10, … seconds strictly before the probed video duration and retain exactly one ongoing annotated action under start ≤ t < end. This is a fixed initial training protocol, not evaluation over every possible moment.", "", "Both tasks use 16 distinct individual timestamped source frames, uniformly spaced by integer source-frame index inside [max(0,t−5),t], plus up to eight actions completed by t, ordered by end time. Explain additionally supplies the clean main action to explain and excludes its annotation ID from history. Track supplies no current-action name. History comes only from structured main verb/object pairs, with purpose/how clauses stripped; original narration, high-level activity, reasons and future annotations are held outside model inputs. Repeated words in input and targets are allowed.", "", "Explain targets use <why> with the exact explicitly stated reason span; Track targets use <action>. Both optionally include <goal> with the uniquely associated annotated activity at query time (activity intervals use start ≤ t < end). Missing or ambiguous activity supervision omits the goal tag and is recorded in the scoring sidecar. Neither task creates an unknown-goal target. <next> contains exactly three actions whose starts are strictly greater than t, from the same video, ordered by (start,end,narration ID). End-of-video cases with fewer than three are excluded.", "", "Source videos were all inspected as 30 fps CFR with zero start time and 1/15360 time base. Text records first plan frame indices using decimal endpoint arithmetic. Extraction independently checks every selected decoder PTS and records actual source timestamps, PTS, time base, source index, hash and path. Training images preserve aspect ratio at maximum edge 384 pixels, RGB JPEG quality 85 with no chroma subsampling. Review contact sheets are never training inputs.", "", "ms-swift exports contain only messages and absolute image paths, following the [official custom-dataset format](https://swift.readthedocs.io/en/latest/Customization/Custom-dataset.html). Each user message has exactly 16 <image> placeholders paired in order with timestamp captions. Reasons, goals and next actions are assistant targets; source IDs and verb/noun class IDs are separate scoring metadata. Missing noun class IDs stay null.", "", "## Measured counts by participant", "", table(["Participant", "Partition", "Explain", "Track", "Total"], [[person, p, total(p,person,'explain'), total(p,person,'track'), total(p,person)] for person in [f'P{i:02}' for i in range(1,10)] for p in PARTITIONS if person in manifest['partitions'][p]['participants']]), "", "## Reason extraction and human review", "", f"{counts['reason_labels_accepted_before_protocol_filter']:,} narration reasons pass conservative rule checks before future-action/frame filters; {counts['explain_records']:,} become Explain records. No generic 'to' extraction is used because many occurrences are locations or action descriptions. Accepted rules are so_that, in_order_to, because, and so_can. Exact original strings, narration IDs, target actions/timestamps, extraction rules, and zero-based half-open character offsets are retained in reason_labels.jsonl and scoring sidecars.", "", "Each marker must bind to the main annotated verb and object in its preceding sentence, with no intervening parsed action. Explicit anaphoric bridges may link the previous sentence. Unlinked incidental observations, negative 'can't', reasons for failed outcomes/other events, missing targets and multiple markers are rejected. These are conservative checks, not a claim of semantic correctness. Human review is still required.", "", table(["Extraction rule", *PARTITIONS, "Total"], [[rule, *[total(p,task='explain',kind='reason_rule',category=rule) for p in PARTITIONS], total(task='explain',kind='reason_rule',category=rule)] for rule in sorted(set(x['category'] for x in dimensions if x['kind']=='reason_rule'))]), "", "[reason_review.csv](reason_review.csv) contains 50 accepted records stratified across rules and participants plus 20 rejected narrations. Columns ‘valid purpose?’, ‘correct target action?’, and ‘reviewer notes’ are blank for the human reviewer. Accepted rows are sampled from the actual Explain records, not merely pre-filter candidates.", "", "Reason rejection counts across all source annotations:", "", table(["Category", "Count"], [[cat,total(kind='reason_labels',category=cat)] for cat in sorted(set(x['category'] for x in dimensions if x['kind']=='reason_labels' and x['category']!='accepted_pending_human_review'))]), "", "## Skips and unavailable labels", "", table(["Task", "Category", *PARTITIONS, "Total"], [[task,cat,*[total(p,task=task,kind='skipped',category=cat) for p in PARTITIONS],total(task=task,kind='skipped',category=cat)] for task in ('explain','track') for cat in sorted(set(x['category'] for x in dimensions if x['kind']=='skipped' and x['task']==task))]), "", "Track gaps and overlapping actions are counted separately and before the future-action filter. Thus skip categories are mutually exclusive by the first failed protocol condition; they do not count every possible additional rejection on the same query. Explain narrations without accepted reasons are counted in the reason-label table above.", "", table(["Goal status", *PARTITIONS, "Total"], [[cat,*[total(p,kind='goal',category=cat) for p in PARTITIONS],total(kind='goal',category=cat)] for cat in ('available','missing_activity','ambiguous_activity')]), "", "Source annotation issues: " + ", ".join(f"{k}: {v}" for k,v in sorted(Counter(x['category'] for x in issues).items())) + ". The two activity rows with P09-2024623-154547 are explicitly aliased to the uniquely matching local video P09-20240623-154547. Original and resolved IDs are preserved; source files are unchanged. See source_annotation_issues.json.", "", "All participant × partition × task × extraction-rule / missing-label / skip-category counts are machine-readable in [counts.csv](counts.csv) and counts.json. Per-query exclusions are in skipped_queries.jsonl.", "", "## Historical E0/E1 benchmark overlap", "", table(["Historical group", *PARTITIONS], [[role,*[benchmark['counts'].get(f'{role}:{p}',0) for p in PARTITIONS]] for role in ('dev','historically_reserved')]), "", f"Of the historically reserved questions, {len(benchmark['eligible_question_ids']['validation'])} validation questions and {len(benchmark['eligible_question_ids']['test'])} test questions remain eligible for fresh held-out evaluation. Their exact IDs are in benchmark_overlap.json; every old question's video membership and eligibility are in benchmark_overlap.csv. Questions whose source videos enter either training partition are ineligible as held out. Historical dev questions on P07–P09 remain video-disjoint from training but have prior development exposure, so are not a fresh held-out benchmark.", "", "## Validation and frame cache", "", f"All {audit['records_verified']:,} final records passed frame ordering, actual timestamp ≤ query, lookback, history completion, target exclusion, three strict future starts, missing-goal omission, exact reason spans and metadata separation checks. Frame paths and SHA256 values were checked. A {sample_audit['records_verified']}-record sample spanning all four partitions and both tasks passed the complete record audit before bulk extraction. No semantic correctness claim is implied by these checks.", "", f"Sample-based full JPEG-cache estimate: {sample_audit['estimated_full_cache_bytes'] / 1024**3:.3f} GiB for {sample_audit['full_requested_unique_frames']:,} unique requested frames. Actual audited JPEG cache: {audit['frame_cache_bytes'] / 1024**3:.3f} GiB, {audit['unique_frames_verified']:,} frames. Cache JSON and filesystem overhead are additional. The 16-frame references are deduplicated by source video/frame index. Extraction resumes from per-video manifests and reuses frames only after identity/timestamp/hash checks; incompatible historical E0/E1 image preprocessing is left untouched.", "", f"Historical E0/E1 preservation check: {preserved}; {len(files):,} saved artifacts compared with the before snapshot. See preservation_audit.json. Source-annotation and output SHA256 values are saved for reruns.", "", "## Deliverables and exact rerun", "", "```bash", f"cd {project}", "bash scripts/prepare_hdepic_sft.sh", "```", "", "The launcher uses .venvs/llavaction/bin/python (existing pandas, PyAV and Pillow), writes datasets/hdepic_sft_v1, and uses 16 frame workers with two decode threads each. HDEPIC_DATA_ROOT, HDEPIC_PREP_OUTPUT, HDEPIC_PREP_PYTHON and HDEPIC_FRAME_WORKERS can override those paths/settings. An existing fixed split manifest is validated and retained. No dependency installation or training launcher is needed.", "", "- text/{partition}.jsonl: full pre-extraction protocol records and source/scoring metadata.", "- swift/{partition}.jsonl: Qwen/ms-swift messages and 16 absolute individual image paths.", "- swift/{partition}.scoring.jsonl: aligned row indices, source IDs, reason spans, goal labels, future actions, verb/noun IDs and actual frame provenance.", "- swift/{partition}.records.jsonl: readable exported records with stable IDs for inspection.", "- split_manifest.json: fixed explicit video membership and measured source duration.", "- reason_review.csv: pending human label review.", "- previews/examples.html and previews/examples.md: ten readable input–target examples with 16-frame previews.", "- counts.csv / counts.json, benchmark_overlap.csv / .json, source_annotation_issues.json, skipped_queries.jsonl, sample_audit.json, timestamp_leakage_audit.json and preservation_audit.json: measured audits.", "", "The dataset is complete as a preparation artifact and remains pending human reason-label review. Stop here before initial SFT, extra-SFT or GRPO.", ""]
    atomic_write_text(out / "README.md", "\n".join(lines))
    with (out / "README.md").open("a") as handle:
        handle.write("\n- swift/{partition}.prompts.jsonl contains only system/user messages and the same images in the same row order; use second_stage.prompts.jsonl for the later GRPO prompt pool, with labels kept in the separate scoring sidecar.\n")
        handle.write("\nTagged target bodies escape XML-sensitive &, < and >; unescape entities when comparing with the verbatim annotations in scoring metadata.\n")
    print(f"Measured report saved: {out / 'README.md'}; historical artifacts unchanged: {preserved}", flush=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUT)
    report(parser.parse_args().output.resolve())


if __name__ == "__main__":
    main()
